import { Component } from '@angular/core';
import { StepsTabsComponent, Tab } from "../../../shared/steps-tabs/steps-tabs.component";
import { ActivatedRoute, Router, RouterOutlet } from '@angular/router';
import { UtilsService } from '../../../services/utils.service';
import { SolicitudApoyo } from '../../../models/solicitud.apoyo';
import { SolicitudApoyoService } from '../../../controllers/solicitud.apoyo.service';
import { SolicitudApoyoModalidad } from '../../../models/solicitud.apoyo.modalidad';


const STEPTABS:Tab[] = [
  {
    key: "datos-personales",
    title: "",
    header: 'Datos Personales',
  },
  {
    key: "negocio",
    title: "",
    header: 'Negocio',
  },
  {
    key: "modalidades",
    title: "",
    header: 'Modalidades',
  },
  {
    key: "inversion-programa",
    title: "",
    header: 'Inversión',
  },
  {
    key:'documentos',
    title:'',
    header:'Documentos'
  },
  {
    key:'datos-bancarios',
    title:'',
    header:'Cotizacion'
  }
]


@Component({
    selector: 'app-form-apoyos',
    imports: [
    StepsTabsComponent,
    RouterOutlet
],
    templateUrl: './form-apoyos.component.html',
    styleUrl: './form-apoyos.component.css'
})
export class FormApoyosComponent {
  tabulador:Tab[]=STEPTABS
  id:number=0
  solicitudApoyo?:SolicitudApoyo
  modalidadActual?:SolicitudApoyoModalidad

  actual_page:number=0

  constructor(
    public solicitudApoyoController: SolicitudApoyoService,
    private utils:UtilsService, 
    private router: Router, 
    private route: ActivatedRoute
  ){}

  ngOnInit(){
    this.route.params.subscribe(async (params)=>{
      this.id=params['apoyo_id']
      if(this.id){
        this.solicitudApoyo=await this.solicitudApoyoController.find(this.id,["solicitudesApoyosModalidades.modalidadesMinistraciones.modalidades",])
        this.modalidadActual= this.solicitudApoyoController.modalidadActual(this.solicitudApoyo)
      }
    })
  }
  navigate(index:number){
    this.router.navigate([this.tabulador[index].key], { relativeTo: this.route });
  }
}
